import React from 'react';
import { useState, useEffect, useCallback } from 'react';
import { Modal, ModalHeader, ModalBody } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { CommonLoader } from 'views/admin/Common/Loader';
import { formResMessage } from 'utils/commonFunc';
import colors from 'config/colors';
import {
  fetchInventoryCategoriesApi,
  saveInventoryCategoryApi,
  updateInventoryCategoryApi,
} from 'actions/admin/inventory';
import CategoryFormModal from './CategoryFormModal';

// Categories are just item metadata, not a workflow of their own - folded in here as a small modal
// launched from the Items tab instead of a standalone top-level tab.
const ManageCategoriesModal = ({ isOpen, schoolId, loggedUserToken, showWarning, onClose, onChanged }) => {
  const [categories, setCategories] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editCategory, setEditCategory] = useState(null);
  const [saving, setSaving] = useState(false);

  const fetchCategories = useCallback(() => {
    setIsLoading(true);
    fetchInventoryCategoriesApi({ schoolId, token: loggedUserToken })
      .then(res => setCategories(res.data || []))
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setIsLoading(false));
  }, [schoolId, loggedUserToken]);

  useEffect(() => {
    if (isOpen) fetchCategories();
  }, [isOpen, fetchCategories]);

  const openAdd = () => {
    setEditCategory(null);
    setIsFormOpen(true);
  };

  const openEdit = inventoryCategoryId => {
    setEditCategory(categories.find(c => c.inventoryCategoryId === inventoryCategoryId));
    setIsFormOpen(true);
  };

  const handleSave = async formData => {
    setSaving(true);
    try {
      if (editCategory) {
        await updateInventoryCategoryApi({ postData: { ...editCategory, ...formData }, token: loggedUserToken });
      } else {
        await saveInventoryCategoryApi({ postData: { ...formData, schoolId, active: true }, token: loggedUserToken });
      }
      showWarning('Saved successfully', 'success');
      setSaving(false);
      setIsFormOpen(false);
      setEditCategory(null);
      fetchCategories();
      onChanged && onChanged();
    } catch (err) {
      setSaving(false);
      showWarning(formResMessage(err), 'error');
    }
  };

  // Takes the id, looks the pristine category up from state - see ItemsTab's toggleActive for why
  // (the row object MuiTable hands back also carries a JSX status badge, which breaks JSON.stringify).
  const toggleActive = async inventoryCategoryId => {
    const category = categories.find(c => c.inventoryCategoryId === inventoryCategoryId);
    try {
      await updateInventoryCategoryApi({ postData: { ...category, active: !category.active }, token: loggedUserToken });
      showWarning(category.active ? 'Category deactivated' : 'Category activated', 'success');
      fetchCategories();
      onChanged && onChanged();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
  };

  const rows = categories.map(c => ({
    ...c,
    statusLabel: c.active ? (
      <span className="active-span">Active</span>
    ) : (
      <span className="deactive-span">Inactive</span>
    ),
  }));

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose} className="modal-offset-sidebar">
      <ModalHeader toggle={onClose}>
        <span style={{ fontSize: 18, whiteSpace: 'nowrap' }}>Manage Categories</span>
      </ModalHeader>
      <ModalBody>
        <div style={{ textAlign: 'right', marginBottom: 10 }}>
          <CustomButton
            size="small"
            name="+ Add Category"
            onClick={openAdd}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </div>
        {isLoading ? (
          <CommonLoader />
        ) : (
          <MuiTable
            tableHeaders={['Category Name', 'Notes', 'Status', 'Action']}
            tableBodyData={{ content: rows }}
            bodyColumns={['categoryName', 'description', 'statusLabel', 'action']}
            idName="inventoryCategoryId"
            dropDownActions={['edit']}
            fetchItem={openEdit}
            hidePagination={true}
            renderRowExtra={item => (
              <CustomButton
                size="small"
                variant="outlined"
                onClick={() => toggleActive(item.inventoryCategoryId)}
                name={item.active ? 'Deactivate' : 'Activate'}
              />
            )}
          />
        )}
      </ModalBody>
      <CategoryFormModal
        isOpen={isFormOpen}
        editCategory={editCategory}
        saving={saving}
        onClose={() => setIsFormOpen(false)}
        onSave={handleSave}
      />
    </Modal>
  );
};

export default ManageCategoriesModal;
