import React from 'react';
import { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useHistory, useLocation } from 'react-router-dom';
import { Paper, Tabs, Tab } from '@material-ui/core';
import { getGlobalSchoolUtils } from 'utils/commonFunc';
import { showToast } from 'actions/admin/auth';
import colors from 'config/colors';
import ItemsTab from './components/ItemsTab';
import PurchasesTab from './components/PurchasesTab';
import StudentIssuesTab from './components/StudentIssuesTab';

// Three tabs matching the actual flow: Items (catalog + categories + current stock), Purchases
// (an expense - buying stock in), Issue to Student (handing stock out; billed to the student via a
// custom bill of type INVENTORY, so there's no separate inventory income).
// Categories/Stock/Transactions used to each get their own top-level tab; that was over-engineered
// for what's really just "manage the catalog" and "view an audit trail" - categories now live in a
// modal off Items, stock is columns on the Items table, and the standalone transaction log was
// dropped since Purchases/Issue-to-student already show that same activity where it happens.
const SUB_TABS = [
  { key: 'items', label: 'Items' },
  { key: 'purchases', label: 'Purchases' },
  { key: 'studentIssues', label: 'Issue to Student' },
];

// Inventory: categories -> items -> purchases (which push stock up and log a PURCHASE
// transaction) -> student-wise issue/return (which pulls stock down/up and logs an
// ISSUED/RETURN transaction). Backend is fully built already; this page is entirely new. Admin
// gating happens one level up, in AdminRoutes.jsx's accessRoles for this route.
const InventoryPage = () => {
  const dispatch = useDispatch();
  const history = useHistory();
  const location = useLocation();
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const globalSchool = getGlobalSchoolUtils();
  const schoolId = globalSchool?.schoolId;
  // Tab lives in the URL (?tab=items) so a refresh - or a link someone shares - lands back on the
  // same tab instead of always resetting to Categories.
  const [activeTab, setActiveTab] = useState(() => {
    const tabKey = new URLSearchParams(location.search).get('tab');
    const index = SUB_TABS.findIndex(tab => tab.key === tabKey);
    return index >= 0 ? index : 0;
  });

  const changeTab = (event, index) => {
    setActiveTab(index);
    history.push(`${location.pathname}?tab=${SUB_TABS[index].key}`);
  };

  const showWarning = (message, type) => dispatch(showToast(message, type));

  if (!schoolId) {
    return (
      <div className="content">
        <div style={{ textAlign: 'center', color: '#9a9a9a', padding: 40 }}>Please select a school.</div>
      </div>
    );
  }

  const tabProps = { schoolId, loggedUserToken, showWarning };
  const tabContent = [
    <ItemsTab key="items" {...tabProps} />,
    <PurchasesTab key="purchases" {...tabProps} />,
    <StudentIssuesTab key="studentIssues" {...tabProps} />,
  ];

  return (
    <div className="content">
      <Paper square style={{ marginBottom: 16 }}>
        <Tabs
          value={activeTab}
          onChange={changeTab}
          TabIndicatorProps={{ style: { display: 'none' } }}
          textColor="inherit"
          variant="scrollable"
          scrollButtons="on">
          {SUB_TABS.map((tab, index) => (
            <Tab
              key={tab.key}
              label={tab.label}
              style={{
                fontWeight: 'bold',
                color: activeTab === index ? colors.accent : '',
                borderBottom: activeTab === index ? `3px solid ${colors.accent}` : '',
              }}
            />
          ))}
        </Tabs>
      </Paper>
      {tabContent[activeTab]}
    </div>
  );
};

export default InventoryPage;
