import React from 'react';
import { useState, useEffect, useCallback } from 'react';
import { Row, Col } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { CommonLoader } from 'views/admin/Common/Loader';
import { formResMessage } from 'utils/commonFunc';
import colors from 'config/colors';
import {
  fetchInventoryItemsApi,
  fetchInventoryCategoriesApi,
  fetchInventoryStocksApi,
  saveInventoryItemApi,
  updateInventoryItemApi,
} from 'actions/admin/inventory';
import ItemFormModal from './ItemFormModal';
import ManageCategoriesModal from './ManageCategoriesModal';

// Items is the one catalog/stock screen - categories (just item metadata) are managed from a modal
// launched here rather than their own tab, and current stock is shown as columns on this same list
// rather than a separate Stock tab, since "how many of X do I have" is really a property of the
// item, not an independent workflow. Low stock is a highlight on the row itself (available <=
// reorder level), not a separate filtered view.
const ItemsTab = ({ schoolId, loggedUserToken, showWarning }) => {
  const [items, setItems] = useState([]);
  const [categories, setCategories] = useState([]);
  const [stocksByItem, setStocksByItem] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [saving, setSaving] = useState(false);
  const [isCategoriesOpen, setIsCategoriesOpen] = useState(false);

  const fetchAll = useCallback(() => {
    setIsLoading(true);
    Promise.all([
      fetchInventoryItemsApi({ schoolId, token: loggedUserToken }),
      fetchInventoryCategoriesApi({ schoolId, token: loggedUserToken }),
      fetchInventoryStocksApi({ schoolId, token: loggedUserToken }),
    ])
      .then(([itemsRes, categoriesRes, stocksRes]) => {
        setItems(itemsRes.data || []);
        setCategories(categoriesRes.data || []);
        // Stock is tracked per-batch, so sum across batches to get one "current stock" figure per item.
        const totals = {};
        (stocksRes.data || []).forEach(s => {
          const t = totals[s.inventoryItemId] || { availableQuantity: 0, issuedQuantity: 0, damagedQuantity: 0 };
          t.availableQuantity += s.availableQuantity || 0;
          t.issuedQuantity += s.issuedQuantity || 0;
          t.damagedQuantity += s.damagedQuantity || 0;
          totals[s.inventoryItemId] = t;
        });
        setStocksByItem(totals);
      })
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setIsLoading(false));
  }, [schoolId, loggedUserToken]);

  useEffect(() => {
    if (schoolId) fetchAll();
  }, [schoolId, fetchAll]);

  const openAdd = () => {
    setEditItem(null);
    setIsModalOpen(true);
  };

  const openEdit = inventoryItemId => {
    setEditItem(items.find(i => i.inventoryItemId === inventoryItemId));
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditItem(null);
  };

  const handleSave = async formData => {
    setSaving(true);
    try {
      if (editItem) {
        await updateInventoryItemApi({ postData: { ...editItem, ...formData }, token: loggedUserToken });
      } else {
        await saveInventoryItemApi({ postData: { ...formData, schoolId, active: true }, token: loggedUserToken });
      }
      showWarning('Saved successfully', 'success');
      setSaving(false);
      closeModal();
      fetchAll();
    } catch (err) {
      setSaving(false);
      showWarning(formResMessage(err), 'error');
    }
  };

  // Takes the id, not the row object MuiTable's renderRowExtra hands back - that row also carries
  // the JSX status badge built below for display, and spreading THAT into the PUT body sends
  // React's internal fiber refs to axios's JSON.stringify, which fails with "Converting circular
  // structure to JSON".
  const toggleActive = async inventoryItemId => {
    const item = items.find(i => i.inventoryItemId === inventoryItemId);
    // Deactivating only retires the item from the catalog (it drops out of the active-items lists
    // used for new issues/purchases). Units already issued stay with their students and their
    // bills are untouched - so allow it, but make that explicit when some are out.
    const issuedQty = stocksByItem[inventoryItemId]?.issuedQuantity || 0;
    if (
      item.active &&
      issuedQty > 0 &&
      !window.confirm(
        `${issuedQty} unit(s) of "${item.itemName}" are currently issued to students. Deactivating only stops new issues - existing issues and bills are not affected. Deactivate anyway?`
      )
    ) {
      return;
    }
    try {
      await updateInventoryItemApi({ postData: { ...item, active: !item.active }, token: loggedUserToken });
      showWarning(item.active ? 'Item deactivated' : 'Item activated', 'success');
      fetchAll();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
  };

  const activeCategories = categories.filter(c => c.active);

  const rows = items.map(i => {
    const stock = stocksByItem[i.inventoryItemId] || { availableQuantity: 0, issuedQuantity: 0, damagedQuantity: 0 };
    const isLowStock = i.reorderLevel > 0 && stock.availableQuantity <= i.reorderLevel;
    return {
      ...i,
      priceLabel: `₹${i.price}`,
      stockLabel: (
        <span style={isLowStock ? { color: '#c62828', fontWeight: 'bold' } : undefined}>
          {stock.availableQuantity}
          {isLowStock ? ' (Low)' : ''}
        </span>
      ),
      issuedLabel: stock.issuedQuantity,
      statusLabel: i.active ? (
        <span className="active-span">Active</span>
      ) : (
        <span className="deactive-span">Inactive</span>
      ),
    };
  });

  if (isLoading) return <CommonLoader />;

  return (
    <>
      <Row className="mb-2" style={{ alignItems: 'center' }}>
        <Col style={{ textAlign: 'right', display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
          <CustomButton
            size="small"
            variant="outlined"
            name="Manage Categories"
            onClick={() => setIsCategoriesOpen(true)}
          />
          <CustomButton
            size="small"
            name="+ Add Item"
            disabled={!activeCategories.length}
            onClick={openAdd}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </Col>
      </Row>
      {!activeCategories.length && (
        <div style={{ color: '#9a9a9a', fontSize: 13, marginBottom: 8 }}>
          Add an active category first (use &quot;Manage Categories&quot; above) before adding items.
        </div>
      )}
      <MuiTable
        tableHeaders={['Item Name', 'Code', 'Category', 'Unit', 'Price', 'Available', 'Issued', 'Status', 'Action']}
        tableBodyData={{ content: rows }}
        bodyColumns={[
          'itemName',
          'itemCode',
          'categoryName',
          'unit',
          'priceLabel',
          'stockLabel',
          'issuedLabel',
          'statusLabel',
          'action',
        ]}
        idName="inventoryItemId"
        dropDownActions={['edit']}
        fetchItem={openEdit}
        hidePagination={true}
        renderRowExtra={item => (
          <CustomButton
            size="small"
            variant="outlined"
            onClick={() => toggleActive(item.inventoryItemId)}
            name={item.active ? 'Deactivate' : 'Activate'}
          />
        )}
      />
      <ItemFormModal
        isOpen={isModalOpen}
        editItem={editItem}
        categories={activeCategories}
        saving={saving}
        onClose={closeModal}
        onSave={handleSave}
      />
      <ManageCategoriesModal
        isOpen={isCategoriesOpen}
        schoolId={schoolId}
        loggedUserToken={loggedUserToken}
        showWarning={showWarning}
        onClose={() => setIsCategoriesOpen(false)}
        onChanged={fetchAll}
      />
    </>
  );
};

export default ItemsTab;
