import axios from 'axios';
import constants from '../../config/constants';

// Plain (non-thunk) axios calls - the inventory backend module doesn't have a redux slice, so
// every screen in views/admin/Inventory calls these directly and keeps its own local state,
// matching how fetchActiveInventoryItemsApi (below) was already being used before this file grew.
const BASE = constants.API_BASE_URL;

const APIS = {
  categories: '/api/admin/inventory/categories',
  items: '/api/admin/inventory/items',
  purchase: '/api/inventory/purchase',
  stocks: '/api/admin/inventory/stocks',
  studentInventory: '/api/admin/inventory/studentvise',
};

// -------------------- Categories -------------------- //

export const fetchInventoryCategoriesApi = data =>
  axios.get(
    `${BASE}${APIS.categories}${constants.makeParams({ schoolId: data.schoolId })}`,
    constants.setHeader(data.token)
  );

export const saveInventoryCategoryApi = data =>
  axios.post(`${BASE}${APIS.categories}`, data.postData, constants.setHeader(data.token));

// Also used to deactivate/reactivate a category (postData carries the full dto with `active` flipped)
// - there's no dedicated delete flow here since removing a category out from under items that
// still reference it isn't something the backend endpoint contract makes safe to assume.
export const updateInventoryCategoryApi = data =>
  axios.put(`${BASE}${APIS.categories}`, data.postData, constants.setHeader(data.token));

// -------------------- Items -------------------- //

// Read-only: reuses the existing (backend-only, no dashboard UI yet) inventory catalog so a
// purchase can be linked to a real item (books, uniform, scarf, ...) when one exists.
export const fetchActiveInventoryItemsApi = data => {
  return axios.get(
    `${BASE}${APIS.items}/active${constants.makeParams({ schoolId: data.schoolId })}`,
    constants.setHeader(data.token)
  );
};

export const fetchInventoryItemsApi = data =>
  axios.get(
    `${BASE}${APIS.items}${constants.makeParams({ schoolId: data.schoolId })}`,
    constants.setHeader(data.token)
  );

export const saveInventoryItemApi = data =>
  axios.post(`${BASE}${APIS.items}`, data.postData, constants.setHeader(data.token));

// Same deactivate/reactivate-via-PUT approach as categories, for the same reason.
export const updateInventoryItemApi = data =>
  axios.put(`${BASE}${APIS.items}`, data.postData, constants.setHeader(data.token));

// -------------------- Purchases -------------------- //
// Create + list only - the backend has no update/delete for a purchase once made (it already
// mutated stock and wrote a transaction row as a side effect, so there's nothing safe to "edit").

export const createInventoryPurchaseApi = data =>
  axios.post(
    `${BASE}${APIS.purchase}${constants.makeParams({ schoolId: data.schoolId })}`,
    data.postData,
    constants.setHeader(data.token)
  );

export const fetchInventoryPurchasesApi = data =>
  axios.get(
    `${BASE}${APIS.purchase}${constants.makeParams({ schoolId: data.schoolId })}`,
    constants.setHeader(data.token)
  );

// -------------------- Stock -------------------- //
// Read-only - the backend deliberately has no create/update for stock, it's only ever moved by
// Purchase (+) and Student Issue/Return (-/+).

export const fetchInventoryStocksApi = data =>
  axios.get(`${BASE}${APIS.stocks}/${data.schoolId}`, constants.setHeader(data.token));

// -------------------- Student-wise (issue / return) -------------------- //

export const fetchStudentInventoryByStatusApi = data =>
  axios.get(
    `${BASE}${APIS.studentInventory}/status/${data.status}${constants.makeParams({ schoolId: data.schoolId })}`,
    constants.setHeader(data.token)
  );

export const fetchStudentInventoryByStudentApi = data =>
  axios.get(
    `${BASE}${APIS.studentInventory}/student/${data.studentId}${constants.makeParams({ schoolId: data.schoolId })}`,
    constants.setHeader(data.token)
  );

export const issueInventoryToStudentApi = data =>
  axios.post(`${BASE}${APIS.studentInventory}`, data.postData, constants.setHeader(data.token));

// Also used to mark an issued item RETURNED - the backend's update path special-cases that status
// transition to move the quantity back into available stock (see StudentInventoryServiceImpl).
export const updateStudentInventoryApi = data =>
  axios.put(`${BASE}${APIS.studentInventory}`, data.postData, constants.setHeader(data.token));
