import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';

const emptyForm = { categoryName: '', description: '' };

const validate = data => {
  const errors = {};
  if (!data.categoryName?.trim()) errors.categoryName = 'Category name is required';
  return errors;
};

const CategoryFormModal = ({ isOpen, editCategory, saving, onClose, onSave }) => {
  const [data, setData] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setData(
        editCategory
          ? { categoryName: editCategory.categoryName, description: editCategory.description || '' }
          : emptyForm
      );
      setErrors({});
    }
  }, [isOpen]);

  const handleChange = (name, value) => setData(prev => ({ ...prev, [name]: value }));

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data);
    setErrors(nextErrors);
    if (!Object.keys(nextErrors).length) onSave(data);
  };

  return (
    <Modal size="md" isOpen={isOpen} toggle={onClose}>
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>{editCategory ? 'UPDATE CATEGORY' : 'ADD CATEGORY'}</ModalHeader>
        <ModalBody>
          <Row>
            <Col md={12}>
              <CustomInput
                label={
                  <>
                    Category Name<sup> *</sup>
                  </>
                }
                name="categoryName"
                value={data.categoryName}
                onChange={handleChange}
                error={errors.categoryName}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                label="Notes"
                name="description"
                type="textarea"
                placeholder="Optional..."
                value={data.description}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Save"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default CategoryFormModal;
