import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';

const emptyForm = {
  inventoryCategoryId: null,
  itemName: '',
  itemCode: '',
  unit: '',
  size: '',
  color: '',
  price: '',
  reorderLevel: 0,
  description: '',
};

const validate = data => {
  const errors = {};
  if (!data.inventoryCategoryId) errors.inventoryCategoryId = 'Category is required';
  if (!data.itemName?.trim()) errors.itemName = 'Item name is required';
  if (!data.itemCode?.trim()) errors.itemCode = 'Item code is required';
  if (data.price === '' || Number(data.price) < 0) errors.price = 'Price is required';
  return errors;
};

const ItemFormModal = ({ isOpen, editItem, categories, saving, onClose, onSave }) => {
  const [data, setData] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setData(
        editItem
          ? {
              inventoryCategoryId: editItem.inventoryCategoryId,
              itemName: editItem.itemName,
              itemCode: editItem.itemCode,
              unit: editItem.unit || '',
              size: editItem.size || '',
              color: editItem.color || '',
              price: editItem.price,
              reorderLevel: editItem.reorderLevel || 0,
              description: editItem.description || '',
            }
          : emptyForm
      );
      setErrors({});
    }
  }, [isOpen]);

  const handleChange = (name, value) => setData(prev => ({ ...prev, [name]: value }));

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data);
    setErrors(nextErrors);
    if (!Object.keys(nextErrors).length) {
      onSave({ ...data, price: Number(data.price), reorderLevel: Number(data.reorderLevel) || 0 });
    }
  };

  const categoryOptions = categories.map(c => ({ label: c.categoryName, value: c.inventoryCategoryId }));

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>{editItem ? 'UPDATE ITEM' : 'ADD ITEM'}</ModalHeader>
        <ModalBody>
          <Row>
            <Col sm={6}>
              <CustomSelect
                label="Category"
                name="inventoryCategoryId"
                isRequired
                usePortal
                value={data.inventoryCategoryId}
                options={categoryOptions}
                onChange={handleChange}
                error={errors.inventoryCategoryId}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Item Name<sup> *</sup>
                  </>
                }
                name="itemName"
                value={data.itemName}
                onChange={handleChange}
                error={errors.itemName}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Item Code<sup> *</sup>
                  </>
                }
                name="itemCode"
                value={data.itemCode}
                onChange={handleChange}
                error={errors.itemCode}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Price<sup> *</sup>
                  </>
                }
                name="price"
                type="number"
                value={data.price}
                onChange={handleChange}
                error={errors.price}
              />
            </Col>
            <Col sm={4}>
              <CustomInput
                label="Unit"
                name="unit"
                placeholder="pcs, box, ..."
                value={data.unit}
                onChange={handleChange}
              />
            </Col>
            <Col sm={4}>
              <CustomInput label="Size" name="size" value={data.size} onChange={handleChange} />
            </Col>
            <Col sm={4}>
              <CustomInput label="Color" name="color" value={data.color} onChange={handleChange} />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Reorder Level"
                name="reorderLevel"
                type="number"
                value={data.reorderLevel}
                onChange={handleChange}
              />
            </Col>
            <Col sm={12}>
              <CustomInput
                label="Notes"
                name="description"
                type="textarea"
                placeholder="Optional..."
                value={data.description}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Save"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default ItemFormModal;
