import React from 'react';
import { useState, useEffect, useCallback } from 'react';
import { Row, Col } from 'reactstrap';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { CommonLoader } from 'views/admin/Common/Loader';
import { formResMessage, getGlobalCurrentBatchUtils, formatMoney, formStudentSelectList } from 'utils/commonFunc';
import colors from 'config/colors';
import { fetchStudentClassDirectoryApi } from 'actions/admin/students';
import {
  fetchStudentInventoryByStatusApi,
  fetchActiveInventoryItemsApi,
  issueInventoryToStudentApi,
} from 'actions/admin/inventory';
import { createCustomBillApi, fetchBatchBillsApi, BILL_TYPE, STUDENT_INVENTORY_REF } from 'actions/admin/billing';
import IssueInventoryModal from './IssueInventoryModal';
import IssueBillModal from './IssueBillModal';
import BillReceiptLinks from 'views/admin/Common/BillReceiptLinks';

const StudentIssuesTab = ({ schoolId, loggedUserToken, showWarning }) => {
  const { batchId } = getGlobalCurrentBatchUtils();
  const [issues, setIssues] = useState([]);
  const [studentsLoading, setStudentsLoading] = useState(false);
  const [catalogItems, setCatalogItems] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  // studentInventoryId -> the INVENTORY bill already raised for it (if any)
  const [billsByIssue, setBillsByIssue] = useState({});
  // studentId -> { student, className, batchId }. The issue record only carries studentId, and the
  // batch student endpoint caps its page size at 50, so this is built from each class's (unpaged)
  // student list instead - which also gives the class for the Student column.
  const [directory, setDirectory] = useState({});
  const [billingIssue, setBillingIssue] = useState(null);
  const [billSaving, setBillSaving] = useState(false);

  // Bills for issued items live in the custom bills table (billType INVENTORY, referenceId =
  // studentInventoryId), and there's no lookup by reference - so pull the bills of each batch the
  // issued items belong to and index the inventory ones. Lets a row show "Billed" instead of
  // offering a second bill for the same issue.
  const fetchIssueBills = useCallback(
    issueList => {
      const batchIds = [...new Set(issueList.map(i => i.batchId).filter(Boolean))];
      return Promise.all(batchIds.map(id => fetchBatchBillsApi({ schoolId, batchId: id, token: loggedUserToken })))
        .then(results => {
          const map = {};
          results.forEach(res =>
            (res.data || []).forEach(bill => {
              if (bill.billType === BILL_TYPE.INVENTORY && bill.referenceType === STUDENT_INVENTORY_REF) {
                map[bill.referenceId] = bill;
              }
            })
          );
          setBillsByIssue(map);
        })
        .catch(err => showWarning(formResMessage(err), 'error'));
    },
    [schoolId, loggedUserToken]
  );

  const fetchDirectory = useCallback(
    issueList => {
      const batchIds = [...new Set([batchId, ...issueList.map(i => i.batchId)].filter(Boolean))];
      setStudentsLoading(true);
      return fetchStudentClassDirectoryApi({ batchIds, token: loggedUserToken })
        .then(setDirectory)
        .catch(err => showWarning(formResMessage(err), 'error'))
        .finally(() => setStudentsLoading(false));
    },
    [loggedUserToken, batchId]
  );

  const fetchIssued = useCallback(() => {
    setIsLoading(true);
    fetchStudentInventoryByStatusApi({ schoolId, status: 'ISSUED', token: loggedUserToken })
      .then(res => {
        const list = res.data || [];
        setIssues(list);
        return Promise.all([fetchIssueBills(list), fetchDirectory(list)]);
      })
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setIsLoading(false));
  }, [schoolId, loggedUserToken, fetchIssueBills, fetchDirectory]);

  const loadCatalog = () => {
    if (catalogItems.length) return;
    fetchActiveInventoryItemsApi({ schoolId, token: loggedUserToken })
      .then(res => setCatalogItems(res.data || []))
      .catch(err => showWarning(formResMessage(err), 'error'));
  };

  useEffect(() => {
    if (schoolId) {
      fetchIssued();
      // Needed up front: the bill modal suggests price x quantity.
      loadCatalog();
    }
  }, [schoolId, fetchIssued]);

  const openIssueModal = () => {
    setIsModalOpen(true);
    loadCatalog();
  };

  const handleAddBill = async billData => {
    setBillSaving(true);
    try {
      await createCustomBillApi({
        postData: {
          ...billData,
          studentId: billingIssue.studentId,
          schoolId,
          batchId: billingIssue.batchId,
          billName: billingIssue.itemName,
          billDate: moment().format('YYYY-MM-DDTHH:mm:ss'),
          billType: BILL_TYPE.INVENTORY,
          referenceType: STUDENT_INVENTORY_REF,
          referenceId: billingIssue.studentInventoryId,
        },
        token: loggedUserToken,
      });
      showWarning('Bill added to the student', 'success');
      setBillingIssue(null);
      fetchIssueBills(issues);
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    } finally {
      setBillSaving(false);
    }
  };

  const handleIssue = async formData => {
    setSaving(true);
    try {
      await issueInventoryToStudentApi({ postData: { ...formData, schoolId, batchId }, token: loggedUserToken });
      showWarning('Item issued successfully', 'success');
      setSaving(false);
      setIsModalOpen(false);
      fetchIssued();
    } catch (err) {
      setSaving(false);
      showWarning(formResMessage(err), 'error');
    }
  };

  const nameLabel = entry => formStudentSelectList([entry.student])[0].label;
  // Current batch's students only - that's who an item can be issued to (the issue is stamped with
  // the current batch).
  const studentOptions = Object.values(directory)
    .filter(entry => entry.batchId === batchId)
    .map(entry => ({
      ...entry.student,
      label: `${nameLabel(entry)} [${entry.className}]`,
      value: entry.student.studentId,
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
  const priceByItemId = {};
  catalogItems.forEach(item => {
    priceByItemId[item.inventoryItemId] = item.price;
  });
  const labelFor = studentId => (directory[studentId] ? nameLabel(directory[studentId]) : `Student #${studentId}`);
  const classFor = studentId => directory[studentId]?.className;
  // The bill amount must be a whole number > 0 on the backend; price x quantity is only a suggestion
  // (blank when the item has no price) and stays editable in the modal.
  const suggestedAmountFor = issue =>
    issue ? Math.round(Number(priceByItemId[issue.inventoryItemId] || 0) * Number(issue.quantity || 0)) : 0;

  const rows = issues.map(i => ({
    ...i,
    studentLabel: (
      <span>
        {labelFor(i.studentId)}
        {classFor(i.studentId) && <span style={{ color: '#9a9a9a' }}> [{classFor(i.studentId)}]</span>}
      </span>
    ),
    issueDateLabel: i.issueDate ? moment(i.issueDate).format('DD MMM, YYYY') : '--',
  }));

  if (isLoading) return <CommonLoader />;

  return (
    <>
      <Row className="mb-2">
        <Col style={{ textAlign: 'right' }}>
          <CustomButton
            size="small"
            name="+ Issue Item"
            onClick={openIssueModal}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </Col>
      </Row>
      <div style={{ color: '#9a9a9a', fontSize: 12, marginBottom: 8 }}>
        Showing items currently issued to students. Use Add Bill to charge the student - it shows up under their
        Billings as an Inventory bill.
      </div>
      <MuiTable
        tableHeaders={['Student', 'Item', 'Quantity', 'Issue Date', 'Action']}
        tableBodyData={{ content: rows }}
        bodyColumns={['studentLabel', 'itemName', 'quantity', 'issueDateLabel', 'action']}
        idName="studentInventoryId"
        hidePagination={true}
        renderRowExtra={item => {
          const bill = billsByIssue[item.studentInventoryId];
          return (
            <>
              {bill ? (
                <div>
                  <span style={{ fontSize: 12, fontWeight: 'bold', color: '#2e7d32', whiteSpace: 'nowrap' }}>
                    Billed {formatMoney(bill.amount)}
                  </span>
                  <div style={{ fontSize: 12 }}>
                    <BillReceiptLinks billId={bill.studentCustomBillId} status={bill.status} schoolId={schoolId} />
                  </div>
                </div>
              ) : (
                <CustomButton
                  size="small"
                  name="Add Bill"
                  onClick={() => setBillingIssue(item)}
                  style={{ backgroundColor: colors.accent, color: colors.white }}
                />
              )}
            </>
          );
        }}
      />
      <IssueInventoryModal
        isOpen={isModalOpen}
        studentOptions={studentOptions}
        studentsLoading={studentsLoading}
        catalogItems={catalogItems}
        saving={saving}
        onClose={() => setIsModalOpen(false)}
        onSave={handleIssue}
      />
      <IssueBillModal
        isOpen={!!billingIssue}
        issue={billingIssue}
        studentLabel={
          billingIssue
            ? `${labelFor(billingIssue.studentId)}${
                classFor(billingIssue.studentId) ? ` [${classFor(billingIssue.studentId)}]` : ''
              }`
            : ''
        }
        suggestedAmount={suggestedAmountFor(billingIssue)}
        saving={billSaving}
        onClose={() => setBillingIssue(null)}
        onSave={handleAddBill}
      />
    </>
  );
};

export default StudentIssuesTab;
