import React from 'react';
import { useState, useEffect, useCallback } from 'react';
import { Row, Col } from 'reactstrap';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { CommonLoader } from 'views/admin/Common/Loader';
import { formResMessage, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import colors from 'config/colors';
import {
  fetchInventoryPurchasesApi,
  fetchActiveInventoryItemsApi,
  createInventoryPurchaseApi,
} from 'actions/admin/inventory';
import PurchaseFormModal from './PurchaseFormModal';

// e.g. "PARTIALLY_PAID" -> "Partially Paid"
const formatEnumLabel = value =>
  value
    ? value
        .toLowerCase()
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ')
    : '--';

const PurchasesTab = ({ schoolId, loggedUserToken, showWarning }) => {
  const [purchases, setPurchases] = useState([]);
  const [catalogItems, setCatalogItems] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const fetchAll = useCallback(() => {
    setIsLoading(true);
    Promise.all([
      fetchInventoryPurchasesApi({ schoolId, token: loggedUserToken }),
      fetchActiveInventoryItemsApi({ schoolId, token: loggedUserToken }),
    ])
      .then(([purchasesRes, itemsRes]) => {
        setPurchases(purchasesRes.data || []);
        setCatalogItems(itemsRes.data || []);
      })
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setIsLoading(false));
  }, [schoolId, loggedUserToken]);

  useEffect(() => {
    if (schoolId) fetchAll();
  }, [schoolId, fetchAll]);

  const handleSave = async formData => {
    setSaving(true);
    try {
      const { batchId } = getGlobalCurrentBatchUtils();
      await createInventoryPurchaseApi({ schoolId, postData: { ...formData, batchId }, token: loggedUserToken });
      showWarning('Purchase recorded successfully', 'success');
      setSaving(false);
      setIsModalOpen(false);
      fetchAll();
    } catch (err) {
      setSaving(false);
      showWarning(formResMessage(err), 'error');
    }
  };

  const rows = purchases.map(p => ({
    ...p,
    totalAmountLabel: `₹${p.totalAmount}`,
    unitPriceLabel: `₹${p.unitPrice}`,
    paymentStatusLabel: formatEnumLabel(p.paymentStatus),
    purchaseDateLabel: p.purchaseDate ? moment(p.purchaseDate).format('DD MMM, YYYY') : '--',
  }));

  if (isLoading) return <CommonLoader />;

  return (
    <>
      <Row className="mb-2">
        <Col style={{ textAlign: 'right' }}>
          <CustomButton
            size="small"
            name="+ Add Purchase"
            disabled={!catalogItems.length}
            onClick={() => setIsModalOpen(true)}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </Col>
      </Row>
      {!catalogItems.length && (
        <div style={{ color: '#9a9a9a', fontSize: 13, marginBottom: 8 }}>
          Add at least one active item before recording a purchase.
        </div>
      )}
      <MuiTable
        tableHeaders={[
          'Item',
          'Qty',
          'Unit Price',
          'Total',
          'Supplier',
          'Invoice #',
          'Payment Status',
          'Purchase Date',
        ]}
        tableBodyData={{ content: rows }}
        bodyColumns={[
          'itemName',
          'quantity',
          'unitPriceLabel',
          'totalAmountLabel',
          'supplierName',
          'invoiceNumber',
          'paymentStatusLabel',
          'purchaseDateLabel',
        ]}
        idName="inventoryPurchaseId"
        hidePagination={true}
      />
      <PurchaseFormModal
        isOpen={isModalOpen}
        catalogItems={catalogItems}
        saving={saving}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSave}
      />
    </>
  );
};

export default PurchasesTab;
