import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';

const validate = data => {
  const errors = {};
  if (!data.amount || Number(data.amount) <= 0) errors.amount = 'Enter a valid amount';
  else if (!Number.isInteger(Number(data.amount))) errors.amount = 'Amount must be a whole number';
  return errors;
};

// Raises a custom bill (billType INVENTORY) against one issued item. Student and item are fixed -
// they come from the issue record - so the only inputs are what the school actually decides:
// amount (suggested as item price x quantity), due date and notes.
const IssueBillModal = ({ isOpen, issue, studentLabel, suggestedAmount, saving, onClose, onSave }) => {
  const [data, setData] = useState({ amount: '', dueDate: '', description: '' });
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setData({
        amount: suggestedAmount ? String(suggestedAmount) : '',
        dueDate: '',
        description: issue ? `${issue.itemName} x ${issue.quantity}` : '',
      });
      setErrors({});
    }
  }, [isOpen, issue, suggestedAmount]);

  const handleChange = (name, value) => setData(prev => ({ ...prev, [name]: value }));

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length) return;
    onSave({
      amount: Number(data.amount),
      dueDate: data.dueDate || null,
      description: data.description?.trim() || null,
    });
  };

  return (
    <Modal size="md" isOpen={isOpen} toggle={onClose} className="modal-offset-sidebar">
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>ADD BILL FOR ISSUED ITEM</ModalHeader>
        <ModalBody>
          <div style={{ fontSize: 13, color: '#6b778a', marginBottom: 14 }}>
            <div>
              Student: <b>{studentLabel}</b>
            </div>
            <div>
              Item: <b>{issue ? `${issue.itemName} x ${issue.quantity}` : '--'}</b>
            </div>
          </div>
          <Row>
            <Col md={12}>
              <CustomInput
                type="number"
                label={
                  <>
                    Amount<sup> *</sup>
                  </>
                }
                name="amount"
                placeholder="Enter amount"
                value={data.amount}
                onChange={handleChange}
                error={errors.amount}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                type="date"
                label="Due date (optional)"
                name="dueDate"
                value={data.dueDate}
                onChange={handleChange}
                error={errors.dueDate}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                label="Notes (optional)"
                name="description"
                value={data.description}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Save Bill"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default IssueBillModal;
