import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';

const emptyForm = { studentId: null, inventoryItemId: null, quantity: 1, remarks: '' };

const validate = data => {
  const errors = {};
  if (!data.studentId) errors.studentId = 'Select a student';
  if (!data.inventoryItemId) errors.inventoryItemId = 'Select an item';
  if (!data.quantity || Number(data.quantity) <= 0) errors.quantity = 'Quantity must be greater than 0';
  return errors;
};

const IssueInventoryModal = ({ isOpen, studentOptions, catalogItems, studentsLoading, saving, onClose, onSave }) => {
  const [data, setData] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setData(emptyForm);
      setErrors({});
    }
  }, [isOpen]);

  const handleChange = (name, value) => setData(prev => ({ ...prev, [name]: value }));

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data);
    setErrors(nextErrors);
    if (!Object.keys(nextErrors).length) {
      onSave({
        studentId: data.studentId,
        inventoryItemId: data.inventoryItemId,
        quantity: Number(data.quantity),
        remarks: data.remarks?.trim() || '',
      });
    }
  };

  const itemOptions = catalogItems.map(item => ({
    label: `${item.itemName} (${item.categoryName})`,
    value: item.inventoryItemId,
  }));

  return (
    <Modal size="md" isOpen={isOpen} toggle={onClose} className="modal-offset-sidebar">
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>ISSUE ITEM TO STUDENT</ModalHeader>
        <ModalBody>
          <Row>
            <Col md={12}>
              <CustomSelect
                label="Student"
                name="studentId"
                isRequired
                usePortal
                loading={studentsLoading}
                placeholder="Search a student by name or register number..."
                value={data.studentId}
                options={studentOptions}
                onChange={handleChange}
                error={errors.studentId}
              />
            </Col>
            <Col md={12}>
              <CustomSelect
                label="Item"
                name="inventoryItemId"
                isRequired
                usePortal
                placeholder="Select an item..."
                value={data.inventoryItemId}
                options={itemOptions}
                onChange={handleChange}
                error={errors.inventoryItemId}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                label={
                  <>
                    Quantity<sup> *</sup>
                  </>
                }
                name="quantity"
                type="number"
                value={data.quantity}
                onChange={handleChange}
                error={errors.quantity}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                label="Remarks"
                name="remarks"
                type="textarea"
                placeholder="Optional..."
                value={data.remarks}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Issue"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default IssueInventoryModal;
