import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import moment from 'moment';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';

const emptyForm = {
  inventoryItemId: null,
  quantity: 1,
  unitPrice: '',
  supplierName: '',
  invoiceNumber: '',
  invoiceDate: moment().format('YYYY-MM-DD'),
  paymentMode: '',
  paidAmount: 0,
  dueDate: '',
  remarks: '',
};

const validate = data => {
  const errors = {};
  if (!data.inventoryItemId) errors.inventoryItemId = 'Select an item';
  if (!data.quantity || Number(data.quantity) <= 0) errors.quantity = 'Quantity must be greater than 0';
  if (data.unitPrice === '' || Number(data.unitPrice) < 0) errors.unitPrice = 'Unit price is required';
  if (!data.supplierName?.trim()) errors.supplierName = 'Supplier name is required';
  return errors;
};

// Purchases can only be created, never edited or deleted here - the backend has no update path
// for one (it already moved stock and logged a transaction as a side effect of creating it).
const PurchaseFormModal = ({ isOpen, catalogItems, saving, onClose, onSave }) => {
  const [data, setData] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setData(emptyForm);
      setErrors({});
    }
  }, [isOpen]);

  const itemOptions = catalogItems.map(item => ({
    label: `${item.itemName} (${item.categoryName})`,
    value: item.inventoryItemId,
  }));

  const handleChange = (name, value) => setData(prev => ({ ...prev, [name]: value }));

  const handleItemSelect = (name, value) => {
    const catalogItem = catalogItems.find(item => item.inventoryItemId === value);
    setData(prev => ({ ...prev, inventoryItemId: value, unitPrice: catalogItem?.price ?? prev.unitPrice }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data);
    setErrors(nextErrors);
    if (!Object.keys(nextErrors).length) {
      onSave({
        inventoryItemId: data.inventoryItemId,
        quantity: Number(data.quantity),
        unitPrice: Number(data.unitPrice),
        supplierName: data.supplierName.trim(),
        invoiceNumber: data.invoiceNumber.trim(),
        invoiceDate: data.invoiceDate || null,
        purchaseDate: moment().toISOString(),
        paymentMode: data.paymentMode.trim(),
        paidAmount: Number(data.paidAmount) || 0,
        dueDate: data.dueDate || null,
        remarks: data.remarks?.trim() || '',
      });
    }
  };

  const total = (Number(data.quantity) || 0) * (Number(data.unitPrice) || 0);

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>ADD PURCHASE</ModalHeader>
        <ModalBody>
          <Row>
            <Col sm={6}>
              <CustomSelect
                label="Item"
                name="inventoryItemId"
                isRequired
                usePortal
                placeholder="Select an item..."
                value={data.inventoryItemId}
                options={itemOptions}
                onChange={handleItemSelect}
                error={errors.inventoryItemId}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Quantity<sup> *</sup>
                  </>
                }
                name="quantity"
                type="number"
                value={data.quantity}
                onChange={handleChange}
                error={errors.quantity}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Unit Price<sup> *</sup>
                  </>
                }
                name="unitPrice"
                type="number"
                value={data.unitPrice}
                onChange={handleChange}
                error={errors.unitPrice}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Total Amount"
                name="totalAmount"
                value={total.toFixed(2)}
                disabled
                onChange={() => {}}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Supplier Name<sup> *</sup>
                  </>
                }
                name="supplierName"
                value={data.supplierName}
                onChange={handleChange}
                error={errors.supplierName}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Invoice Number"
                name="invoiceNumber"
                value={data.invoiceNumber}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Invoice Date"
                name="invoiceDate"
                type="date"
                value={data.invoiceDate}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Payment Mode"
                name="paymentMode"
                placeholder="Cash, UPI, ..."
                value={data.paymentMode}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Paid Amount"
                name="paidAmount"
                type="number"
                value={data.paidAmount}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomInput label="Due Date" name="dueDate" type="date" value={data.dueDate} onChange={handleChange} />
            </Col>
            <Col sm={12}>
              <CustomInput
                label="Remarks"
                name="remarks"
                type="textarea"
                placeholder="Optional..."
                value={data.remarks}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Save"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default PurchaseFormModal;
